PRAGMA foreign_keys = ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE functions(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, start_address INTEGER NOT NULL, end_address INTEGER, start_line INTEGER NOT NULL, end_line INTEGER);
CREATE INDEX functions_address ON functions(start_address, end_address);
CREATE TABLE lines(line_number INTEGER PRIMARY KEY, address INTEGER, function_id INTEGER REFERENCES functions(id), text TEXT NOT NULL);
CREATE INDEX lines_address ON lines(address);
CREATE INDEX lines_function ON lines(function_id, line_number);
CREATE TABLE symbols(name TEXT PRIMARY KEY, address INTEGER NOT NULL, kind TEXT NOT NULL, line_number INTEGER NOT NULL REFERENCES lines(line_number), function_id INTEGER REFERENCES functions(id));
CREATE INDEX symbols_address ON symbols(address);
CREATE TABLE instructions(id INTEGER PRIMARY KEY, address INTEGER UNIQUE, line_number INTEGER UNIQUE NOT NULL REFERENCES lines(line_number), function_id INTEGER REFERENCES functions(id), mnemonic TEXT NOT NULL, operands TEXT NOT NULL, flow_kind TEXT NOT NULL, is_indirect INTEGER NOT NULL DEFAULT 0);
CREATE INDEX instructions_function ON instructions(function_id, address);
CREATE INDEX instructions_mnemonic ON instructions(mnemonic, address);
CREATE TABLE refs(id INTEGER PRIMARY KEY, source_address INTEGER, source_line INTEGER NOT NULL REFERENCES lines(line_number), source_function INTEGER REFERENCES functions(id), target_address INTEGER, target_symbol TEXT, kind TEXT NOT NULL, expression TEXT NOT NULL);
CREATE INDEX refs_target ON refs(target_address, kind);
CREATE INDEX refs_symbol ON refs(target_symbol, kind);
CREATE INDEX refs_source ON refs(source_address, kind);
CREATE INDEX refs_function ON refs(source_function, kind);
CREATE TABLE annotations(address INTEGER PRIMARY KEY, name TEXT, note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'unreviewed');
CREATE VIRTUAL TABLE source_fts USING fts5(text, content='lines', content_rowid='line_number');
CREATE VIEW calls AS SELECT r.*, s.function_id AS target_function FROM refs r LEFT JOIN symbols s ON s.name=r.target_symbol WHERE r.kind='call';
CREATE VIEW function_summary AS SELECT f.*, (SELECT count(*) FROM instructions i WHERE i.function_id=f.id) AS instruction_count, (SELECT count(*) FROM refs r WHERE r.source_function=f.id AND r.kind='call') AS outgoing_calls FROM functions f;
